INSERT INTO `faqs` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES
(1, 'Comment puis-je suivre ma commande ?', '<p>&nbsp;une fois votre commande exp&eacute;di&eacute;e, vous recevrez un SMS de confirmation.</p>', '2023-09-27 12:43:23', '2023-09-27 12:43:23'),
(2, 'Comment puis-je passer une commande sur votre site ?', '<h3>&nbsp;Pour passer une commande, suivez ces &eacute;tapes :</h3>\r\n<p>Choisissez les produits que vous souhaitez acheter en les ajoutant &agrave; votre panier.<br>Cliquez sur &nbsp;le button \"afficher votre panier\".<br>Suivez les instructions pour saisir vos informations de livraison.<br>Cliquez sur le bouton \"Passer commande\".</p>', '2023-09-27 12:49:26', '2023-09-27 12:49:26'),
(3, 'Qu\'est-ce que votre entreprise propose?', '<p>Notre entreprise propose [description succincte des produits/services].</p>', '2023-09-29 14:13:21', '2023-09-29 14:13:21'),
(4, 'Comment puis-je passer une commande?', '<p>Pour passer une commande, rendez-vous sur notre page [Commandes] et suivez les instructions simples.</p>', '2023-09-29 14:14:08', '2023-09-29 14:14:08'),
(5, 'Quels sont les modes de paiement acceptés?', '<p>Nous acceptons les paiements par [liste des modes de paiement accept&eacute;s].</p>', '2023-09-29 14:14:45', '2023-09-29 14:14:45'),
(6, 'Quelle est la politique de livraison?', '<p>Notre politique de livraison est disponible sur la page [Livraison], o&ugrave; vous trouverez des d&eacute;tails sur les d&eacute;lais et les frais.</p>', '2023-09-29 14:15:18', '2023-09-29 14:15:18'),
(7, 'Puis-je retourner un produit?', '<p>Oui, vous pouvez retourner un produit dans un d&eacute;lai de [nombre de jours] jours apr&egrave;s r&eacute;ception. Consultez notre politique de retour sur la page [Retours] pour plus d\'informations.</p>', '2023-09-29 14:20:21', '2023-09-29 14:20:21'),
(8, 'Comment puis-je suivre ma commande?', '<p>Une fois votre commande exp&eacute;di&eacute;e, vous recevrez un e-mail de confirmation contenant un lien de suivi. Vous pouvez &eacute;galement suivre votre commande en vous connectant &agrave; votre compte sur notre site.</p>', '2023-09-29 14:24:18', '2023-09-29 14:24:18'),
(9, 'Quelle est votre politique de confidentialité?', '<p>Notre politique de confidentialit&eacute; est disponible sur la page [Confidentialit&eacute;], o&ugrave; nous d&eacute;taillons comment nous collectons, utilisons et prot&eacute;geons vos informations.</p>', '2023-09-29 14:24:48', '2023-09-29 14:24:48'),
(10, 'Comment puis-je vous contacter en cas de problème?', '<p>Vous pouvez nous contacter via notre formulaire de contact sur la page [Contact] ou en envoyant un e-mail &agrave; [adresse e-mail].</p>', '2023-09-29 14:25:18', '2023-09-29 14:25:18'),
(11, 'Proposez-vous une assistance clientèle en temps réel?', '<p>Oui, nous proposons une assistance en temps r&eacute;el via notre chat en direct pendant nos heures d\'ouverture indiqu&eacute;es sur la page [Contact].</p>', '2023-09-29 14:26:11', '2023-09-29 14:26:11'),
(12, 'Comment puis-je m\'inscrire à votre newsletter?', '<p>Pour vous inscrire &agrave; notre newsletter, rendez-vous sur la page d\'accueil et saisissez votre adresse e-mail dans le formulaire d\'inscription pr&eacute;vu &agrave; cet effet.</p>', '2023-09-29 14:26:42', '2023-09-29 14:26:42');
